const { ZXFonts8x8 } = await import('./zxFonts8x8.js?ver='+window.srcVersion);
// begin code

/**
 * The keycap font of the ZX dialogs' on-screen keyboard (ZXPlayerNameEntity):
 * ZXFonts8x8 with the glyphs of *Alcatraz Harry 2* (1984) in the library's
 * adapted copy, `fonts/alcatraz-harry-2.svision.ch8.hex.txt` — the same 96
 * characters, with `{ | } ~ ©` redrawn. The extra glyphs of ZXFonts8x8 stay
 * behind the table.
 *
 * The ZX theme names it `zxFonts8x8Keys` (`keyboardFont`); a game does not
 * declare it — {@link ZXFonts8x8Keys.provide} puts it into `app.fonts` when
 * the dialog opens. A game that wants other keycaps sets its own font under
 * that name first, or another `keyboardFont` in its theme.
 */
export class ZXFonts8x8Keys extends ZXFonts8x8 {

  /**
   * @param {Object} app - The application instance.
   * @param {boolean} [proportional] - Trim the glyphs to proportional widths; the keyboard has 8-pixel cells.
   */
  constructor(app, proportional = false) {
    super(app, proportional);
    this.id = 'ZXFonts8x8Keys';

    this.setFontsData('');
  } // constructor

  /**
   * Makes sure the application has the font as `app.fonts.zxFonts8x8Keys`:
   * one the application set itself is left alone.
   * @param {Object} app - The application with its `fonts`.
   * @returns {ZXFonts8x8} The font.
   */
  static provide(app) {
    if (!app.fonts.zxFonts8x8Keys) {
      app.fonts.zxFonts8x8Keys = new ZXFonts8x8Keys(app, false);
    }
    return app.fonts.zxFonts8x8Keys;
  } // provide

} // ZXFonts8x8Keys
